179: /// Serializes a [`Changeset`] back to `.changeset/*.md` bytes.
180: ///
181: /// Names are quoted only when necessary. Severities are always written lowercase. Output
182: /// always uses `\n` line endings and ends with a single trailing newline after the summary.
183: pub fn write_changeset(changeset: &Changeset) -> Result<String, WriteError> {
184:     if changeset.entries.is_empty() && changeset.summary.trim().is_empty() {
185:         return Err(WriteError::EmptyChangeset);
186:     }
187:     for (index, entry) in changeset.entries.iter().enumerate() {
188:         if entry.name.is_empty() {
189:             return Err(WriteError::EmptyName { index });
190:         }
191:         if entry.name.contains('"') {
192:             return Err(WriteError::NameContainsQuote {
193:                 index,
194:                 name: entry.name.clone(),
