199:     let mut out = String::from("---\n");
200:     for entry in &changeset.entries {
201:         if needs_quoting(&entry.name) {
202:             out.push_str(&format!("\"{}\": {}\n", entry.name, entry.severity));
203:         } else {
204:             out.push_str(&format!("{}: {}\n", entry.name, entry.severity));
