5: /// Normalizes a path to be workspace-root-relative and UTF-8.
6: ///
7: /// Rejects absolute paths and non-UTF-8 paths, and normalizes `.` and `..` components
8: /// lexically (without accessing the filesystem).
9: pub fn workspace_relative(path: impl AsRef<Path>) -> Result<PathBuf, ModelError> {
10:     let p = path.as_ref();
11:     if p.is_absolute() {
12:         return Err(ModelError::AbsolutePath {
13:             path: p.to_path_buf(),
14:         });
15:     }
16: 
17:     if p.to_str().is_none() {
18:         return Err(ModelError::NonUtf8Path {
19:             path: p.to_path_buf(),
20:         });
21:     }
22: 
23:     let mut components = Vec::new();
24:     for component in p.components() {
25:         match component {
26:             Component::Prefix(_) | Component::RootDir => {
27:                 return Err(ModelError::AbsolutePath {
28:                     path: p.to_path_buf(),
29:                 });
30:             }
31:             Component::CurDir => {}
32:             Component::ParentDir => {
33:                 if let Some(Component::Normal(_)) = components.last() {
34:                     components.pop();
35:                 } else {
36:                     return Err(ModelError::PathTraversal {
37:                         path: p.to_path_buf(),
38:                     });
39:                 }
40:             }
41:             Component::Normal(_) => {
42:                 components.push(component);
43:             }
44:         }
45:     }
46: 
47:     let mut out = PathBuf::new();
48:     for c in components {
49:         out.push(c.as_os_str());
50:     }
51: 
52:     Ok(out)
53: }
